    public FinancialInstitution testCreate() throws Throwable {
    FinancialInstitution entity = null;

    LOGGER.info( "FinancialInstitutionTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a FinancialInstitution");

    StringBuilder msg = new StringBuilder( "-- Failed to create a FinancialInstitution" );

    try {
        entity = service.createFinancialInstitution( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getFinancialInstitutionId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a FinancialInstitution with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

