    /**
     * Tests getting all FinancialInstitutions.
     *
     * @return    Collection
     */
    public List<FinancialInstitution> testGetAll() throws Throwable {
    LOGGER.info( "FinancialInstitutionTest:testGetAll() - Retrieving Collection of FinancialInstitutions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all FinancialInstitution : " );
    List<FinancialInstitution> collection  = null;

    try {
        // call the static get method on the FinancialInstitutionService
        collection = service.getAllFinancialInstitution();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            FinancialInstitution currEntity  = null;
            Iterator<FinancialInstitution> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getFinancialInstitutionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

